// «Orchestration турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

const targets = [
  { name: "a", healthy: true },
  { name: "b", healthy: false },
  { name: "c", healthy: true },
];
const state = { i: 0 };

window.SEQ = [
  nextTarget(targets, state),
  nextTarget(targets, state),
  nextTarget(targets, state),
  nextTarget(targets, state),
];

panel("ok", "seq", "Хуваарилалт (b унасан)", [JSON.stringify(window.SEQ)]);
document.body.dataset.ready = "1";

